using System.Globalization;
using Avalonia.Controls;
using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop; public sealed partial class ManagerFiscalizationWindow : Window { private readonly IFiscalizationManager manager; private readonly Guid organizationId; private readonly Guid branchId; public ManagerFiscalizationWindow() => throw new InvalidOperationException("Fiscal runtime is required."); public ManagerFiscalizationWindow(IFiscalizationManager manager, Guid organizationId, Guid branchId) { this.manager = manager ?? throw new ArgumentNullException(nameof(manager)); if (organizationId == Guid.Empty || branchId == Guid.Empty) throw new ArgumentException("Fiscal scope is invalid."); this.organizationId = organizationId; this.branchId = branchId; InitializeComponent(); ScopeText.Text = $"Organization {organizationId:D} · Branch {branchId:D}"; DocumentBox.Text = Guid.NewGuid().ToString("D"); } private void GenerateClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => DocumentBox.Text = Guid.NewGuid().ToString("D"); private async void SubmitClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Execute(async () => Show((await manager.SubmitAsync(organizationId, branchId, new(Guid.Parse(DocumentBox.Text ?? ""), Guid.Parse(SaleBox.Text ?? ""), (ProviderBox.Text ?? "").Trim(), (TypeBox.Text ?? "").Trim(), (CurrencyBox.Text ?? "").Trim().ToUpperInvariant(), decimal.Parse(AmountBox.Text ?? "", CultureInfo.InvariantCulture), PayloadBox.Text ?? ""), default)).Document)); private async void ReadClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Execute(async () => Show(await manager.ReadAsync(organizationId, Guid.Parse(DocumentBox.Text ?? ""), default))); private async void RetryClick(object? s, Avalonia.Interactivity.RoutedEventArgs e) => await Execute(async () => Show((await manager.RetryAsync(organizationId, Guid.Parse(DocumentBox.Text ?? ""), default)).Document)); private void Show(DesktopFiscalDocument v) { StateText.Text = $"{v.Status} · {v.GrossAmount:0.00} {v.Currency} · attempts {v.AttemptCount} · {v.ProviderReference ?? "no reference"}"; AttemptList.ItemsSource = v.Attempts.Select(x => $"#{x.AttemptNumber} {x.Outcome} · {x.ProviderCode ?? "-"} · {x.FailureReason ?? x.ProviderReference ?? "-"}").ToArray(); } private async Task Execute(Func<Task> a) { try { await a(); MessageText.Text = ""; } catch (Exception ex) when (ex is ArgumentException or InvalidOperationException or HttpRequestException or FormatException) { MessageText.Text = ex is HttpRequestException ? "Fiscal service request failed." : ex.Message; } } }
